// config.mjs — a fábrica de configuração.
export function criarConfiguracao(opcoes = {}) {
  if (typeof opcoes !== 'object' || opcoes === null) {
    throw new Error('opções precisa ser um objeto');
  }

  // Defaults: o que o chamador não informar, ganha este valor.
  const porta = opcoes.porta === undefined ? 3000 : opcoes.porta;
  const ambiente = opcoes.ambiente === undefined ? 'desenvolvimento' : opcoes.ambiente;

  // Validação: a fábrica recusa o objeto antes de ele nascer.
  if (!Number.isInteger(porta) || porta < 1 || porta > 65535) {
    throw new Error('porta precisa ser um inteiro entre 1 e 65535');
  }
  const ambienteValido = ['desenvolvimento', 'producao', 'teste'];
  if (!ambienteValido.includes(ambiente)) {
    throw new Error('ambiente precisa ser desenvolvimento, producao ou teste');
  }

  // Objeto NOVO a cada chamada: duas chamadas não compartilham nada.
  return {
    porta,
    ambiente,
    logDetalhado: opcoes.logDetalhado === undefined ? false : opcoes.logDetalhado,
  };
}

// Passo 1: a fábrica de configuração — defaults + validação.
export function criarConfiguracao(opcoes = {}) {
  return {
    porta: opcoes.porta ?? 3000,
    ambiente: opcoes.ambiente ?? 'desenvolvimento',
    logDetalhado: opcoes.logDetalhado ?? false,
  };
}

// Passo 2: a fábrica do app — monta o objeto pronto usando a configuração.
